const D = { energy: .55, scale: 1, density: .55, speed: 1, wet: .5, haze: .5, hue: 20, x: .42, y: .34, style: 'ponds', act: 'evaporate', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 20;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];

const STY = {
  // industrial colour evaporation ponds — pink, rust, teal, green cells; pale salt berms
  ponds:      { skT:[204,26,58], skB:[192,12,80], haze:[196,10,82], berm:[36,8,88], bermS:[34,14,64],
                pal:[[340,50,64],[16,66,60],[180,44,54],[70,50,58],[300,40,56],[40,60,70]], glint:[40,20,98], grain:16, mirror:0, mono:0 },
  // salar: white salt flat with a thin mirror water sheet, minimal colour, sublime
  salar:      { skT:[210,30,54], skB:[204,14,82], haze:[204,12,84], berm:[210,6,92], bermS:[206,10,76],
                pal:[[206,10,86],[204,14,80],[200,8,90],[206,12,82],[202,10,88],[204,10,84]], glint:[204,8,99], grain:12, mirror:1, mono:0 },
  // warm sunset — cells glowing pink-gold, long shadows on the berms
  sunset:     { skT:[262,34,32], skB:[26,44,80], haze:[24,34,72], berm:[30,26,72], bermS:[18,34,48],
                pal:[[350,54,66],[20,68,68],[40,64,72],[320,44,58],[8,60,60],[54,58,72]], glint:[40,40,99], grain:18, mirror:0, mono:0 },
  // ABSTRACTED multispectral false-colour survey — saturated data blocks
  false_color:{ skT:[250,44,12], skB:[250,30,18], haze:[250,24,20], berm:[60,10,30], bermS:[60,14,20],
                pal:[[320,80,88],[54,90,92],[180,80,84],[280,70,80],[120,70,78],[0,80,86]], glint:[60,20,99], grain:5, mirror:0, mono:0 },
  // ABSTRACTED sumi ink — tonal cells + berms, monochrome
  ink:        { skT:[30,5,84], skB:[30,3,74], haze:[30,3,78], berm:[30,4,86], bermS:[30,7,60],
                pal:[[30,5,46],[30,6,58],[30,4,40],[30,5,64],[30,6,52],[30,4,70]], glint:[30,3,90], grain:28, mirror:0, mono:1 }
};
const st = STY[P.style] || STY.ponds;

const en = Math.max(0, Math.min(1, P.energy));
const hz = Math.max(0, Math.min(1, P.haze));
const hzY = height * P.y;                          // horizon
const vx = width * (.3 + P.x * .4);                // vanishing bias
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

if (!S.field || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.field) { S.field.remove(); S.haze.remove(); }
  S.field = mk(W, H); S.haze = mk(W, H);
  const g = S.field; g.noStroke();
  const skT = sh(st.skT), skB = sh(st.skB), hazeC = sh(st.haze), bermC = sh(st.berm), bermS = sh(st.bermS);

  // sky
  for (let yy = 0; yy < Math.ceil(hzY); yy++) { const c = L3(skT, skB, Math.pow(yy / Math.max(1, hzY), .7)); g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1); }
  // distant ridge / plant on the horizon
  g.fill(L3(bermS, hazeC, .7)[0], L3(bermS, hazeC, .7)[1], L3(bermS, hazeC, .7)[2]);
  g.beginShape(); g.vertex(0, hzY);
  for (let x = 0; x <= W; x += u * .05) g.vertex(x, hzY - u * (.01 + fr(Math.floor(x / (u * .05))) * .03));
  g.vertex(W, hzY); g.endShape(g.CLOSE);

  // --- receding pond grid: rows from far (near horizon) to near (foreground) ---
  S.cells = [];
  const NRow = Math.floor(9 + P.density * 9);
  const NCol = Math.floor(6 + P.density * 6);
  for (let r = 0; r < NRow; r++) {
    const nf = r / (NRow - 1);                     // 0 far .. 1 near
    const yA = hzY + Math.pow(nf, 2.0) * (H - hzY);
    const yB = hzY + Math.pow((r + 1) / (NRow - 1), 2.0) * (H - hzY);
    const haze = (1 - nf) * (.5 + .4 * hz);
    // horizontal convergence: far rows narrower toward vx
    const spanNear = 1, spanFar = .12;
    const spanA = spanFar + (spanNear - spanFar) * nf;
    for (let cc = 0; cc < NCol; cc++) {
      const fx0 = (cc) / NCol, fx1 = (cc + 1) / NCol;
      const xA0 = vx + (fx0 - .5) * W * spanA, xA1 = vx + (fx1 - .5) * W * spanA;
      const spanB = spanFar + (spanNear - spanFar) * ((r + 1) / (NRow - 1));
      const xB0 = vx + (fx0 - .5) * W * spanB, xB1 = vx + (fx1 - .5) * W * spanB;
      const pi = Math.floor(fr(r * 40 + cc * 3 + 7) * st.pal.length);
      let col = st.pal[pi];
      col = L3(col, hazeC, haze);
      const wet = st.mirror ? 1 : fr(r * 40 + cc * 3 + 9);
      // cell fill (trapezoid)
      g.fill(col[0], col[1] * (st.mono ? 1 : (.6 + .4 * (1 - haze))), col[2], 100);
      g.beginShape(); g.vertex(xA0, yA); g.vertex(xA1, yA); g.vertex(xB1, yB); g.vertex(xB0, yB); g.endShape(g.CLOSE);
      // crust mottle / concentration variation
      if (!st.mono) {
        for (let m = 0; m < 3; m++) {
          const mf = fr(r * 40 + cc * 5 + m + 11);
          const c2 = L3(col, L3(col, bermC, .4), mf);
          g.fill(c2[0], c2[1], Math.max(2, c2[2] + (fr(m) - .5) * 8), 26);
          g.ellipse((xA0 + xB1) / 2 + (fr(m) - .5) * (xA1 - xA0), (yA + yB) / 2, (xA1 - xA0) * (.4 + mf * .5), (yB - yA) * .5);
        }
      }
      S.cells.push({ xA0: xA0, xA1: xA1, xB0: xB0, xB1: xB1, yA: yA, yB: yB, wet: wet, near: nf, haze: haze, phase: fr(r * 40 + cc + 13) * 6.283, hue: col[0] });
    }
    // berms: pale salt walls between rows
    g.strokeWeight(Math.max(.8, (yB - yA) * .12));
    g.stroke(bermC[0], bermC[1], Math.min(99, L3(bermC, hazeC, haze)[2]), 90);
    g.line(vx - W * spanA * .5, yA, vx + W * spanA * .5, yA);
    g.noStroke();
  }
  // vertical berms
  const NCol2 = Math.floor(6 + P.density * 6);
  g.strokeWeight(Math.max(.8, u * .002));
  for (let cc = 0; cc <= NCol2; cc++) {
    const fx = cc / NCol2;
    g.stroke(bermC[0], bermC[1], Math.min(99, bermC[2] - hz * 6), 60);
    g.line(vx + (fx - .5) * W * .12, hzY, vx + (fx - .5) * W, H);
  }
  g.noStroke();

  // drifting haze / dust band (tileable)
  S.haze.noStroke();
  for (let i = 0; i < 10; i++) {
    const bx = fr(i * 5 + 61) * W, by = hzY - u * .02 + fr(i * 5 + 62) * u * .3;
    const bw = u * (.5 + fr(i * 5 + 63) * 1), bhh = u * (.03 + fr(i * 5 + 64) * .07);
    for (let rep = -1; rep <= 1; rep++) for (let kk = 0; kk < 4; kk++) {
      S.haze.fill(hazeC[0], hazeC[1] * (1 - kk * .1), Math.min(99, hazeC[2] + kk * 2), 7 * (1 - kk * .2));
      S.haze.ellipse(bx + rep * W, by + kk * bhh * .1, bw * (1 - kk * .1), bhh * (1 - kk * .08));
    }
  }
  S.key = key;
}

// ---------------- act ----------------
const sec = ((Math.floor(K.section) % 6) + 6) % 6;
const ACT = { evaporate: { wet: 1, shim: 1, hazek: 1 }, flood: { wet: 1 + sec * .05, shim: .8, hazek: 1 }, dry: { wet: .5, shim: 1.4, hazek: 1.2 } };
const act = ACT[P.act] || ACT.evaporate;
const wet = Math.max(0, Math.min(1.4, P.wet * act.wet));

noStroke();
image(S.field, 0, 0);

// ---------------- heat shimmer near the horizon (undulating translucent air — cheap, no copy) ----------------
const bandTop = Math.max(0, hzY - u * .02);
const bandH = u * .18;
const shimC = sh(st.haze);
noStroke();
const nSh = 14;
for (let i = 0; i < nSh; i++) {
  const f = i / nSh;
  const sy = bandTop + f * bandH;
  const off = Math.sin(sy * .05 + K.t * (1.6 + i * .11) * P.speed * act.shim) * u * .01 * (.4 + en) * act.shim
            + Math.sin(sy * .02 - K.t * 1.1) * u * .006;
  const bright = fr(i) > .5 ? 12 : -12;
  fill(shimC[0], shimC[1] * .5, Math.max(2, Math.min(99, shimC[2] + bright)), 6 * act.shim * (1 - f * .4));
  beginShape();
  for (let x = -u * .05; x <= width + u * .05; x += u * .06) {
    const wob = Math.sin(x * .01 + K.t * (2 + f * 2) + i) * u * .004 * act.shim;
    vertex(x + off, sy + wob);
  }
  for (let x = width + u * .05; x >= -u * .05; x -= u * .06) vertex(x + off, sy + bandH / nSh * 1.4);
  endShape(CLOSE);
}

// ---------------- reflection shimmer + specular glints on the wet cells ----------------
const glintC = sh(st.glint);
blendMode(ADD);
for (const c of S.cells) {
  if (c.wet < .35 && !st.mirror) continue;
  const cx = (c.xA0 + c.xA1 + c.xB0 + c.xB1) / 4;
  const cy = (c.yA + c.yB) / 2;
  const tw = Math.sin(K.t * (.6 + c.near) * P.speed + c.phase) * .5 + .5;
  const gl = (5 + 16 * tw * en) * (c.wet) * (1 - c.haze * .5) * (.4 + wet);
  fill(glintC[0], glintC[1] * (st.mirror ? .6 : .4), glintC[2], gl);
  // a horizontal specular streak that shivers
  const sw = (c.xB1 - c.xB0 + c.xA1 - c.xA0) * .5;
  ellipse(cx + Math.sin(K.t * (.8 + c.near) + c.phase) * sw * .12, cy, sw * (.5 + .4 * tw), (c.yB - c.yA) * .18);
}
blendMode(BLEND);

// slow colour breathing (evaporation) on scattered cells — perpetual, incommensurate
for (const c of S.cells) {
  const breathe = Math.sin(K.t * (.12 + c.near * .15) + c.phase) * .5 + .5;
  if (breathe < .55) continue;
  const cx = (c.xA0 + c.xB0) / 2, cw = (c.xA1 - c.xA0 + c.xB1 - c.xB0) / 2;
  fill(c.hue, 30, 70, (breathe - .55) * 30 * (1 - c.haze));
  quad(c.xA0, c.yA, c.xA1, c.yA, c.xB1, c.yB, c.xB0, c.yB);
}

// drifting haze band over the far pans
const HW = S.haze.width;
const hx = ((-K.t * u * .006 * P.speed * act.hazek % HW) + HW) % HW;
push(); tint(0, 0, 100, 60 * hz + 20); image(S.haze, hx - HW, 0); image(S.haze, hx, 0); pop();

// grain, vignette, alpha
if (st.grain > 6) {
  const ng2 = Math.floor(st.grain * 5);
  for (let i = 0; i < ng2; i++) {
    const gx = ((fr(i * 3 + 401) * width) + Math.sin(K.t * .01 + i) * u * .002 + width) % width;
    const gy = fr(i * 3 + 402) * height;
    fill(st.berm[0], st.berm[1] * .4, fr(i * 3 + 403) > .5 ? 94 : 12, 3 + fr(i) * 5);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .05);
  stroke(sh(st.bermS)[0], st.bermS[1], 10, 16 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();
if (P.alpha < 1) { fill(sh(st.bermS)[0], st.bermS[1] * .5, 10, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
